package singleton.logger;

/**
 * SimpleDemo 类 - 简单演示类
 * 展示Logger的基本功能并验证文件写入
 * Simple demo class to show Logger basic functionality and verify file writing
 */
public class SimpleDemo {
    public static void main(String[] args) {
        System.out.println("=== Logger System Simple Demo ===\n");

        // 获取Logger实例 / Get Logger instance
        Logger logger = Logger.getInstance();

        // 写入几条日志 / Write some logs
        logger.write("First log message");
        logger.write("Second log message");
        logger.write("Third log message");

        System.out.println("\n--- Changing log file ---\n");

        // 更改日志文件 / Change log file
        logger.setFileName("demo.log");
        logger.write("Log after file change - message 1");
        logger.write("Log after file change - message 2");

        // 关闭日志器 / Close logger
        logger.close();

        System.out.println("\n=== Demo Finished ===");
        System.out.println("\nPlease check these files in logs directory:");
        System.out.println("1. application.log (should have 3 lines)");
        System.out.println("2. demo.log (should have 2 lines)");
    }
}

package builder.computers;

public class Computer {
    private String processor;
    private int ram;
    private String hardDrive;
    private String graphicsCard;
    private String operatingSystem;

    public void setProcessor(String processor) {
        this.processor = processor;
    }

    public void setRam(int ram) {
        this.ram = ram;
    }

    public void setHardDrive(String hardDrive) {
        this.hardDrive = hardDrive;
    }

    public void setGraphicsCard(String graphicsCard) {
        this.graphicsCard = graphicsCard;
    }

    public void setOperatingSystem(String operatingSystem) {
        this.operatingSystem = operatingSystem;
    }

    @Override
    public String toString() {
        return "Computer Configuration:\n" +
               "  Processor      : " + processor + "\n" +
               "  RAM            : " + ram + " GB\n" +
               "  Hard Drive     : " + hardDrive + "\n" +
               "  Graphics Card  : " + graphicsCard + "\n" +
               "  Operating System: " + operatingSystem;
    }
}

package builder.computers;

/**
 * 计算机产品类
 * 此类代表被构建的产品，包含计算机的各个硬件组件
 */
public class Computer {
    // 处理器
    private String processor;
    // 内存（GB）
    private int ram;
    // 硬盘
    private String hardDrive;
    // 显卡
    private String graphicsCard;
    // 操作系统
    private String operatingSystem;

    /**
     * 设置处理器
     */
    public void setProcessor(String processor) {
        this.processor = processor;
    }

    /**
     * 设置内存大小
     */
    public void setRam(int ram) {
        this.ram = ram;
    }

    /**
     * 设置硬盘
     */
    public void setHardDrive(String hardDrive) {
        this.hardDrive = hardDrive;
    }

    /**
     * 设置显卡
     */
    public void setGraphicsCard(String graphicsCard) {
        this.graphicsCard = graphicsCard;
    }

    /**
     * 设置操作系统
     */
    public void setOperatingSystem(String operatingSystem) {
        this.operatingSystem = operatingSystem;
    }

    /**
     * 返回计算机配置信息的字符串表示
     */
    @Override
    public String toString() {
        return "Computer Configuration:\n" +
               "  Processor      : " + processor + "\n" +
               "  RAM            : " + ram + " GB\n" +
               "  Hard Drive     : " + hardDrive + "\n" +
               "  Graphics Card  : " + graphicsCard + "\n" +
               "  Operating System: " + operatingSystem;
    }
}

package builder.computers;

public interface ComputerBuilder {
    void buildProcessor();
    void buildRAM();
    void buildHardDrive();
    void buildGraphicsCard();
    void buildOperatingSystem();
    Computer getComputer();
}

package builder.computers;

/**
 * 计算机构建器接口
 * 定义了构建计算机的所有步骤
 * 每个具体构建器都需要实现这些方法
 */
public interface ComputerBuilder {
    /**
     * 构建处理器
     */
    void buildProcessor();

    /**
     * 构建内存
     */
    void buildRAM();

    /**
     * 构建硬盘
     */
    void buildHardDrive();

    /**
     * 构建显卡
     */
    void buildGraphicsCard();

    /**
     * 构建操作系统
     */
    void buildOperatingSystem();

    /**
     * 获取已构建的计算机产品
     * @return 返回构建完成的Computer对象
     */
    Computer getComputer();
}

package builder.computers;

public class ComputerDirector {
    private ComputerBuilder builder;

    public ComputerDirector(ComputerBuilder builder) {
        this.builder = builder;
    }

    public void setBuilder(ComputerBuilder builder) {
        this.builder = builder;
    }

    public void constructComputer() {
        builder.buildProcessor();
        builder.buildRAM();
        builder.buildHardDrive();
        builder.buildGraphicsCard();
        builder.buildOperatingSystem();
    }
}

package builder.computers;

/**
 * 计算机构建导演类
 * 负责按照特定步骤和顺序指挥构建器构建计算机
 * 即使使用不同的构建器，也能确保按照相同的构建流程进行
 */
public class ComputerDirector {
    // 持有一个构建器实例
    private ComputerBuilder builder;

    /**
     * 构造函数
     * @param builder 指定要使用的构建器
     */
    public ComputerDirector(ComputerBuilder builder) {
        this.builder = builder;
    }

    /**
     * 设置或更换构建器
     * @param builder 新的构建器
     */
    public void setBuilder(ComputerBuilder builder) {
        this.builder = builder;
    }

    /**
     * 执行计算机构建过程
     * 按照特定顺序调用构建器的各个构建方法
     */
    public void constructComputer() {
        builder.buildProcessor();
        builder.buildRAM();
        builder.buildHardDrive();
        builder.buildGraphicsCard();
        builder.buildOperatingSystem();
    }
}

package builder.computers;

public class GamingComputerBuilder implements ComputerBuilder {
    private Computer computer;

    public GamingComputerBuilder() {
        this.computer = new Computer();
    }

    @Override
    public void buildProcessor() {
        computer.setProcessor("Intel Core i9-14900K");
    }

    @Override
    public void buildRAM() {
        computer.setRam(32);
    }

    @Override
    public void buildHardDrive() {
        computer.setHardDrive("2 TB NVMe SSD");
    }

    @Override
    public void buildGraphicsCard() {
        computer.setGraphicsCard("NVIDIA GeForce RTX 4090");
    }

    @Override
    public void buildOperatingSystem() {
        computer.setOperatingSystem("Windows 11 Home");
    }

    @Override
    public Computer getComputer() {
        return this.computer;
    }
}

package builder.computers;

/**
 * 游戏电脑构建器
 * 实现ComputerBuilder接口，专门用于构建游戏电脑
 * 配置高性能硬件组件
 */
public class GamingComputerBuilder implements ComputerBuilder {
    // 正在构建的计算机产品
    private Computer computer;

    /**
     * 构造函数
     * 初始化一个新的Computer对象
     */
    public GamingComputerBuilder() {
        this.computer = new Computer();
    }

    /**
     * 为游戏电脑配置高端处理器
     */
    @Override
    public void buildProcessor() {
        computer.setProcessor("Intel Core i9-14900K");
    }

    /**
     * 为游戏电脑配置大容量内存
     */
    @Override
    public void buildRAM() {
        computer.setRam(32);
    }

    /**
     * 为游戏电脑配置高速硬盘
     */
    @Override
    public void buildHardDrive() {
        computer.setHardDrive("2 TB NVMe SSD");
    }

    /**
     * 为游戏电脑配置高端显卡
     */
    @Override
    public void buildGraphicsCard() {
        computer.setGraphicsCard("NVIDIA GeForce RTX 4090");
    }

    /**
     * 为游戏电脑配置操作系统
     */
    @Override
    public void buildOperatingSystem() {
        computer.setOperatingSystem("Windows 11 Home");
    }

    /**
     * 返回已构建的游戏电脑
     */
    @Override
    public Computer getComputer() {
        return this.computer;
    }
}

package builder.computers;

public class Main {
    public static void main(String[] args) {

        // --- Build a Gaming Computer ---
        ComputerBuilder gamingBuilder = new GamingComputerBuilder();
        ComputerDirector director = new ComputerDirector(gamingBuilder);

        director.constructComputer();
        Computer gamingComputer = gamingBuilder.getComputer();

        System.out.println("=== Gaming Computer ===");
        System.out.println(gamingComputer);

        System.out.println();

        // --- Build an Office Computer ---
        ComputerBuilder officeBuilder = new OfficeComputerBuilder();
        director.setBuilder(officeBuilder);

        director.constructComputer();
        Computer officeComputer = officeBuilder.getComputer();

        System.out.println("=== Office Computer ===");
        System.out.println(officeComputer);
    }
}

package builder.computers;

/**
 * 主类 - 演示Builder设计模式的使用
 * 通过导演类和不同的构建器来构建不同类型的电脑
 */
public class Main {
    /**
     * 主方法
     * 演示构建游戏电脑和办公电脑的过程
     */
    public static void main(String[] args) {

        // --- 构建游戏电脑 ---
        // 创建游戏电脑构建器
        ComputerBuilder gamingBuilder = new GamingComputerBuilder();
        // 创建导演，并注入游戏电脑构建器
        ComputerDirector director = new ComputerDirector(gamingBuilder);

        // 导演指挥构建器按照步骤构建电脑
        director.constructComputer();
        // 从构建器获取已构建完成的游戏电脑
        Computer gamingComputer = gamingBuilder.getComputer();

        // 显示游戏电脑配置信息
        System.out.println("=== Gaming Computer ===");
        System.out.println(gamingComputer);

        System.out.println();

        // --- 构建办公电脑 ---
        // 创建办公电脑构建器
        ComputerBuilder officeBuilder = new OfficeComputerBuilder();
        // 为同一个导演更换构建器
        director.setBuilder(officeBuilder);

        // 导演指挥新的构建器按照相同步骤构建电脑
        director.constructComputer();
        // 从构建器获取已构建完成的办公电脑
        Computer officeComputer = officeBuilder.getComputer();

        // 显示办公电脑配置信息
        System.out.println("=== Office Computer ===");
        System.out.println(officeComputer);
    }
}

package builder.computers;

public class OfficeComputerBuilder implements ComputerBuilder {
    private Computer computer;

    public OfficeComputerBuilder() {
        this.computer = new Computer();
    }

    @Override
    public void buildProcessor() {
        computer.setProcessor("Intel Core i5-13500");
    }

    @Override
    public void buildRAM() {
        computer.setRam(16);
    }

    @Override
    public void buildHardDrive() {
        computer.setHardDrive("512 GB SSD");
    }

    @Override
    public void buildGraphicsCard() {
        computer.setGraphicsCard("Intel UHD Graphics 770 (Integrated)");
    }

    @Override
    public void buildOperatingSystem() {
        computer.setOperatingSystem("Windows 11 Pro");
    }

    @Override
    public Computer getComputer() {
        return this.computer;
    }
}

package builder.computers;

/**
 * 办公电脑构建器
 * 实现ComputerBuilder接口，专门用于构建办公电脑
 * 配置适合办公应用的硬件组件
 */
public class OfficeComputerBuilder implements ComputerBuilder {
    // 正在构建的计算机产品
    private Computer computer;

    /**
     * 构造函数
     * 初始化一个新的Computer对象
     */
    public OfficeComputerBuilder() {
        this.computer = new Computer();
    }

    /**
     * 为办公电脑配置中端处理器
     */
    @Override
    public void buildProcessor() {
        computer.setProcessor("Intel Core i5-13500");
    }

    /**
     * 为办公电脑配置适中的内存
     */
    @Override
    public void buildRAM() {
        computer.setRam(16);
    }

    /**
     * 为办公电脑配置标准容量硬盘
     */
    @Override
    public void buildHardDrive() {
        computer.setHardDrive("512 GB SSD");
    }

    /**
     * 为办公电脑配置集成显卡
     */
    @Override
    public void buildGraphicsCard() {
        computer.setGraphicsCard("Intel UHD Graphics 770 (Integrated)");
    }

    /**
     * 为办公电脑配置操作系统
     */
    @Override
    public void buildOperatingSystem() {
        computer.setOperatingSystem("Windows 11 Pro");
    }

    /**
     * 返回已构建的办公电脑
     */
    @Override
    public Computer getComputer() {
        return this.computer;
    }
}
